package com.sanctuarygames.createtransit.radio.client;
import net.minecraft.resources.ResourceLocation;
public final class RadioAcousticsCheck {public static void run(){try{Class.forName("net.minecraft.client.sounds.SoundEngine");Class.forName("com.mojang.blaze3d.audio.Channel");}catch(ClassNotFoundException e){throw new AssertionError(e);}if(net.neoforged.fml.ModList.get().isLoaded("sound_physics_remastered")){try{Class.forName("com.sonicether.soundphysics.SoundPhysics");}catch(ClassNotFoundException e){throw new AssertionError(e);}System.out.println("PASS: official SPR 1.21.1 class transformed with optional Transit mixin.");}var p=new RadioAcoustics.Profile(1,2,3,32,128,.3,1,1,true);RadioAcoustics.publish(java.util.List.of(p));if(RadioAcoustics.find(ResourceLocation.parse("createtransit:station_radio"),1,2,3)!=p||RadioAcoustics.find(ResourceLocation.parse("minecraft:music"),1,2,3)!=null)throw new AssertionError("Radio-only isolation");if(RadioAcoustics.fade(64,32,1)!=0||Math.abs(RadioAcoustics.fade(64,128,1)-.5)>.0001||RadioAcoustics.fade(129,128,1)!=0)throw new AssertionError("Independent direct/wet falloffs");RadioAcoustics.publish(java.util.List.of());System.out.println("PASS: independent direct/reverb gain envelopes and non-radio isolation.");}}
